        string $user,
        ?string $reason = null,
        ?bool $disallowun = null,
        ?bool $leaveFtpAcctsEnabled = null,
    ): void {
        ($this->run)(AccountsSpec::SUSPENDACCT, [
            'user' => $user,
            'reason' => $reason,
            'disallowun' => $disallowun,
            'leaveFtpAcctsEnabled' => $leaveFtpAcctsEnabled,
        ]);
    }

